import pytest

from bubble_sort.cli import format_values, main, parse_values, sorted_values


@pytest.mark.parametrize(
    ("arguments", "expected"),
    [
        ((), [64, 34, 25, 12, 22, 11, 90]),
        (("pear", "apple", "banana"), ["pear", "apple", "banana"]),
    ],
)
def test_parse_values(arguments, expected) -> None:
    assert parse_values(arguments) == expected


@pytest.mark.parametrize(
    ("arguments", "expected"),
    [
        (("5", "1", "3"), [1, 3, 5]),
        (("pear", "apple", "banana"), ["apple", "banana", "pear"]),
    ],
)
def test_sorted_values(arguments, expected) -> None:
    assert sorted_values(arguments) == expected


def test_format_values_uses_list_representation() -> None:
    assert format_values(["apple", "banana", "pear"]) == "['apple', 'banana', 'pear']"


def test_cli_main_prints_sorted_demo_values(capsys) -> None:
    main(())

    assert capsys.readouterr().out == "[11, 12, 22, 25, 34, 64, 90]\n"
